  "chest-700-28": {
    "title": "蝶翼征心源性肺水肿",
    "english": "Pulmonary edema — 蝶翼征心源性肺水肿",
    "modality": "X-RAY",
    "level": "中级",
    "distractors": [
      "多灶肺炎",
      "肺纤维化",
      "气胸"
    ],
    "tags": [
      "双肺阴影",
      "间质征象",
      "胸腔积液"
    ],
    "signs": [
      "观察双肺间质性或肺泡性阴影及分布",
      "检查肺血管重分布、间隔线和支气管袖口征",
      "联合心影大小和双侧胸腔积液判断心源性线索"
    ],
    "basis": "公开来源明确支持“肺水肿”及病例标题所述表现；本例不补造未公开病史。",
    "differential": "ARDS和感染也可产生双肺阴影；心影不大不能完全排除心源性水肿，便携AP片又会放大心影。",
    "pearl": "同一征象要同时看肺、心、血管和胸膜，不能只凭“蝙蝠翼”下结论。",
    "method": "核对AP/PA和吸气程度后，按肺血流、间质、肺泡、心影、胸膜五项顺序阅读。",
    "next": "比较既往片和治疗前后变化，结合超声心动图、BNP等资料判断机制。",
    "tips": [
      "便携AP片的心影放大要谨慎解释。",
      "周围型或不对称水肿可不呈典型中央分布。"
    ],
    "pitfalls": [
      "双肺白影不自动等于感染。",
      "静态片不能单独区分心源性和非心源性水肿。"
    ],
    "recall": "定位 → 蝶翼征心源性肺水肿核心征象 → 评估范围与并发症 → 完整检查确认。",
    "ref": "chest"
  },
