  "chest-700-33": {
    "title": "重度支气管扩张",
    "english": "Bronchiectasis — 重度支气管扩张",
    "modality": "CT",
    "level": "中级",
    "distractors": [
      "肺气肿",
      "蜂窝肺",
      "肺水肿"
    ],
    "tags": [
      "支气管扩张",
      "印戒征",
      "不变细"
    ],
    "signs": [
      "比较支气管内径与伴行动脉，寻找印戒征",
      "观察支气管向外周走行时是否不再逐渐变细",
      "记录柱状、曲张或囊状形态及黏液栓、树芽征和分布"
    ],
    "basis": "公开来源明确支持“支气管扩张”及病例标题所述表现；本例不补造未公开病史。",
    "differential": "牵拉性支气管扩张伴周围纤维化和结构扭曲；急性感染可暂时使支气管显宽，轻度边界病例需结合完整薄层CT。",
    "pearl": "先确认“扩张且不变细”，再按肺叶分布寻找潜在病因。",
    "method": "用薄层CT连续追踪支气管，比较支气管-动脉比例、外周可见度及是否伴结构扭曲。",
    "next": "报告范围、形态、黏液栓和活动性感染征象，并结合临床检查原发或继发原因。",
    "tips": [
      "不要只凭一个印戒样截面，要在连续层面确认。",
      "老年、肺动脉偏细或高原环境可影响支气管-动脉比例。"
    ],
    "pitfalls": [
      "肺纤维化中的牵拉扩张不应脱离纤维化单独解释。",
      "网页拼图不能完成全肺严重度评分。"
    ],
    "recall": "定位 → 重度支气管扩张核心征象 → 评估范围与并发症 → 完整检查确认。",
    "ref": "bronchiectasis"
  },
