  "chest-700-35": {
    "title": "肺气肿胸片",
    "english": "Pulmonary emphysema — 肺气肿胸片",
    "modality": "CT",
    "level": "中级",
    "distractors": [
      "支气管扩张",
      "蜂窝肺",
      "气胸"
    ],
    "tags": [
      "低密度区",
      "血管稀疏",
      "肺大疱"
    ],
    "signs": [
      "在肺窗寻找无明显壁的异常低密度区",
      "评估小叶中心型、全小叶型或间隔旁型分布",
      "检查血管纹理减少、肺大疱和过度充气等伴随改变"
    ],
    "basis": "公开来源明确支持“肺气肿”及病例标题所述表现；本例不补造未公开病史。",
    "differential": "气胸位于脏层胸膜外；蜂窝肺囊腔常有可见壁、层叠和纤维化背景；肺囊肿通常边界更清楚。",
    "pearl": "“低密度”要结合壁、分布和血管改变，不能把正常肺窗黑色区域都当肺气肿。",
    "method": "核对肺窗后从肺尖到肺底比较低密度分布、血管稀疏和肺容积。",
    "next": "完整评估应结合吸烟/暴露史、肺功能及并发肺大疱或肺癌风险。",
    "tips": [
      "窗位不一致会显著改变低密度区观感。",
      "间隔旁型肺气肿常位于胸膜下，需与气胸分开。"
    ],
    "pitfalls": [
      "单张CT不能做可靠定量。",
      "影像严重程度与症状和肺功能并非完全一致。"
    ],
    "recall": "定位 → 肺气肿胸片核心征象 → 评估范围与并发症 → 完整检查确认。",
    "ref": "copd"
  },
