  "chest-700-37": {
    "title": "Macklin效应纵隔气肿",
    "english": "Pneumomediastinum — Macklin效应纵隔气肿",
    "modality": "CT",
    "level": "中级",
    "distractors": [
      "气胸",
      "心包积气",
      "皮下气肿"
    ],
    "tags": [
      "纵隔旁透亮线",
      "连续膈征",
      "颈部气体"
    ],
    "signs": [
      "寻找勾勒主动脉、心缘或气管的线状透亮影",
      "检查气体是否向颈部软组织延伸并伴皮下气肿",
      "评估是否同时存在气胸、胸腔积液或其他食管/气道损伤线索"
    ],
    "basis": "公开来源明确支持“纵隔气肿”及病例标题所述表现；本例不补造未公开病史。",
    "differential": "气胸位于脏层胸膜外；心包积气多局限于心包反折以下；皮肤皱褶可产生伪线。",
    "pearl": "纵隔气肿是征象，关键下一步是根据情境判断自发性、外伤性或食管气道破裂。",
    "method": "沿纵隔轮廓、心缘、膈肌和颈部软组织系统寻找气体，并用CT确认范围和原因。",
    "next": "如有剧烈呕吐、外伤、感染或不稳定表现，应紧急排查食管或气道损伤。",
    "tips": [
      "连续膈征指心影下方膈肌被气体连续勾勒。",
      "侧位片和颈部软组织可显示正位不明显的气体。"
    ],
    "pitfalls": [
      "不能把纵隔气肿自动等同于Boerhaave综合征。",
      "胸片阴性不能排除少量纵隔气体。"
    ],
    "recall": "定位 → Macklin效应纵隔气肿核心征象 → 评估范围与并发症 → 完整检查确认。",
    "ref": "chest"
  },
